"const express = require("express");
const router = express.Router();
const supabase = require("../config/supabase");

// Middleware: Verify Owner Authorization
function verifyOwnerAuth(req, res, next) {
  const authHeader = req.headers.authorization || "";
  const token = authHeader.replace("Bearer ", "").trim() || req.query.token;

  if (!token || token.startsWith("vet_token_")) {
    return res.status(403).json({
      success: false,
      message: "Forbidden. Owner authorization token required."
    });
  }
  next();
}

// GET /api/pets - Get all pets from 'pets' collection table
router.get("/", async function (req, res) {
  try {
    let query = supabase.from('pets').select('*').order('createdAt', { ascending: false });

    if (req.query.type) {
      query = query.ilike('type', `%${req.query.type}%`);
    }
    if (req.query.ownerEmail) {
      query = query.eq('ownerEmail', req.query.ownerEmail);
    }
    if (req.query.ownerPhone) {
      query = query.eq('ownerPhone', req.query.ownerPhone);
    }
    if (req.query.status) {
      query = query.eq('status', req.query.status);
    }
    if (req.query.ownerId) {
      query = query.eq('ownerId', req.query.ownerId);
    }

    const { data: dbPets, error } = await query;
    if (error) throw error;

    return res.json({
      success: true,
      count: dbPets.length,
      collection: "pets",
      data: dbPets
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

